// Extrae TODOS los adjuntos ZIP del mensaje + cuerpo de texto para detectar contraseña
const payload    = $json.payload || {};
const messageId  = $json.id;
const headers    = payload.headers || [];
const getHeader  = (name) => (headers.find(h => h.name.toLowerCase() === name.toLowerCase()) || {}).value || '';

const emailFrom    = getHeader('From')    || '';
const emailSubject = getHeader('Subject') || '(sin asunto)';

// ── Extraer texto plano/HTML del correo (para detectar "Clave de ingreso: ...") ──
function extractTextParts(parts, depth) {
  if (!parts || depth > 6) return '';
  let txt = '';
  for (const part of parts) {
    if ((part.mimeType === 'text/plain' || part.mimeType === 'text/html') && part.body && part.body.data) {
      try {
        txt += Buffer.from(
          part.body.data.replace(/-/g, '+').replace(/_/g, '/'),
          'base64'
        ).toString('utf8') + '\n';
      } catch (_) {}
    }
    if (part.parts) txt += extractTextParts(part.parts, depth + 1);
  }
  return txt;
}

let emailBodyText = extractTextParts(payload.parts || [], 0);
if (!emailBodyText && payload.body && payload.body.data) {
  try {
    emailBodyText = Buffer.from(
      payload.body.data.replace(/-/g, '+').replace(/_/g, '/'),
      'base64'
    ).toString('utf8');
  } catch (_) {}
}

// ── Extraer attachments ZIP ───────────────────────────────────────────────────
function extractParts(parts, depth) {
  if (!parts || depth > 6) return [];
  const found = [];
  for (const part of parts) {
    if (part.filename && part.filename.length > 0 && part.body && part.body.attachmentId) {
      found.push(part);
    }
    if (part.parts) found.push(...extractParts(part.parts, depth + 1));
  }
  return found;
}

const allParts = extractParts(payload.parts || [], 0);

const zips = allParts.filter(p => {
  const fn = (p.filename || '').toLowerCase();
  const mt = (p.mimeType  || '').toLowerCase();
  return fn.endsWith('.zip') || mt.includes('zip') || mt.includes('x-zip') || mt.includes('compressed');
});

if (zips.length === 0) {
  return [{ json: {
    messageId, emailFrom, emailSubject, emailBodyText,
    hasZips: false,
    zipIndex: 0, totalZips: 0,
    zipAttachmentId: '', zipFileName: ''
  }}];
}

// Un ítem por cada ZIP para que HTTP - Descargar ZIP los descargue todos
return zips.map((z, i) => ({ json: {
  messageId, emailFrom, emailSubject, emailBodyText,
  hasZips: true,
  zipIndex: i,
  totalZips: zips.length,
  zipAttachmentId: z.body.attachmentId,
  zipFileName:     z.filename || `adjunto_${i}.zip`,
  zipMimeType:     z.mimeType || 'application/zip'
}}));

// Agrega TODOS los ZIPs descargados en un solo JSON para envío batch al servidor.
// Incluye emailBodyText para que el servidor pueda extraer la contraseña ZIP.
const httpItems = $input.all();   // respuestas de HTTP - Descargar ZIP
const zipMetas  = $('Extraer Todos los ZIPs').all(); // metadata original

if (!httpItems.length) throw new Error('No hay ZIPs descargados');

const infoBase = zipMetas[0]?.json ?? {};

const zipsBase64 = httpItems.map((item, i) => {
  const raw  = item.json.data ?? '';
  if (!raw) throw new Error(`ZIP #${i} (${zipMetas[i]?.json?.zipFileName}) tiene data vacía`);
  const meta = zipMetas[i]?.json ?? {};
  return {
    data:     raw.replace(/-/g, '+').replace(/_/g, '/'), // base64url → base64 estándar
    fileName: meta.zipFileName ?? `adjunto_${i}.zip`,
    mimeType: meta.zipMimeType ?? 'application/zip',
  };
});

return [{
  json: {
    messageId:     infoBase.messageId     ?? '',
    emailFrom:     infoBase.emailFrom     ?? '',
    emailSubject:  infoBase.emailSubject  ?? '',
    emailBodyText: infoBase.emailBodyText ?? '',
    totalZips:     zipsBase64.length,
    zipsBase64,
  }
}];
